69	// SplitTurns produces one Turn per user-prompt line. Token usage for each turn
70	// is computed on the slice [LineStart, LineEnd) so turns don't double-count
71	// later turns. tool_result lines (Type == "user" but no text content) do not
72	// start a turn.
73	func (claudeImporter) SplitTurns(sf SessionFile, full []byte) ([]Turn, error) {
74		subagentsDir := filepath.Join(filepath.Dir(sf.Path), sf.SessionID, "subagents")
75		rawLines := splitRawLines(full)
