77		// Identify user-prompt turn starts in raw-line space.
78		var starts []int
79		for i, raw := range rawLines {
80			if isUserPromptLine(raw) {
81				starts = append(starts, i)
82			}
83		}
84	
85		ag := &claudecode.ClaudeCodeAgent{}
86		turns := make([]Turn, 0, len(starts))
87		for k, start := range starts {
88			end := len(rawLines)
89			if k+1 < len(starts) {
90				end = starts[k+1]
91			}
92	
93			// Bound token usage to [start, end): truncate to the first `end` lines,
94			// then let the agent helper slice from `start`.
95			truncated := joinLines(rawLines[:end])
96			tokens, err := ag.CalculateTotalTokenUsage(truncated, start, subagentsDir)
97			if err != nil {
98				return nil, fmt.Errorf("token usage for turn %d: %w", k, err)
99			}
100	
101			var rec struct {
102				UUID      string          `json:"uuid"`
103				Message   json.RawMessage `json:"message"`
104				Timestamp string          `json:"timestamp"`
105			}
106			if err := json.Unmarshal(rawLines[start], &rec); err != nil {
107				// Already validated as a user-prompt line in isUserPromptLine; skip
108				// defensively if it somehow fails to parse here.
109				continue
110			}
111			ts, parseErr := time.Parse(time.RFC3339, rec.Timestamp)
112			if parseErr != nil {
113				ts = time.Time{}
114			}
115	
116			turns = append(turns, Turn{
117				LineStart: start,
118				LineEnd:   end,
119				UUID:      rec.UUID,
120				Prompt:    transcript.ExtractUserContent(rec.Message),
121				Model:     modelInRange(rawLines, start, end),
122				CreatedAt: ts,
123				Tokens:    tokens,
124			})
125		}
126		return turns, nil
127	}
128	
129	// claudeExtraFields are line fields not modeled by transcript.Line.
130	type claudeExtraFields struct {
131		ParentUUID string `json:"parentUuid"`
132		Timestamp  string `json:"timestamp"`
133		Message    struct {
134			Model string `json:"model"`
135		} `json:"message"`
136	}
137	
138	// modelInRange returns the model from the first assistant message within
139	// [start, end), or "" when none carries one. The model lives on assistant
140	// lines, not the user-prompt line.
141	func modelInRange(rawLines [][]byte, start, end int) string {
142		for i := start; i < end && i < len(rawLines); i++ {
143			var line transcript.Line
144			if err := json.Unmarshal(rawLines[i], &line); err != nil {
145				continue
146			}
147			if line.Type != "assistant" {
148				continue
149			}
150			var ex claudeExtraFields
151			if err := json.Unmarshal(rawLines[i], &ex); err != nil {
152				continue
153			}
154			if ex.Message.Model != "" {
155				return ex.Message.Model
156			}
157		}
158		return ""
159	}
160	
161	// isUserPromptLine reports whether a raw JSONL line is a genuine user-prompt
162	// turn start: type "user" (or role "user") with non-empty extractable text.
163	// tool_result lines are type "user" but carry no text, so they return false.
164	func isUserPromptLine(raw []byte) bool {
165		var line transcript.Line
166		if err := json.Unmarshal(raw, &line); err != nil {
167			return false
168		}
169		typ := line.Type
170		if typ == "" {
171			typ = line.Role
172		}
173		if typ != "user" {
174			return false
175		}
176		return transcript.ExtractUserContent(line.Message) != ""
177	}
178	
179	// splitRawLines splits content into raw lines in the same index space as
180	// transcript.SliceFromLine (newline-counted). Trailing empty segment from a
181	// final newline is dropped.
182	func splitRawLines(content []byte) [][]byte {
183		if len(content) == 0 {
184			return nil
185		}
186		parts := strings.Split(string(content), "\n")
187		if len(parts) > 0 && parts[len(parts)-1] == "" {
188			parts = parts[:len(parts)-1]
189		}
190		out := make([][]byte, len(parts))
191		for i, p := range parts {
192			out[i] = []byte(p)
193		}
194		return out
195	}
196	
197	// joinLines reassembles raw lines into newline-terminated bytes.
198	func joinLines(lines [][]byte) []byte {
199		if len(lines) == 0 {
200			return nil
201		}
202		strs := make([]string, len(lines))
203		for i, l := range lines {
204			strs[i] = string(l)
205		}
206		return []byte(strings.Join(strs, "\n") + "\n")
207	}
