87	// its session_meta payload. The first line must be session_meta by Codex's
88	// format.
89	func codexReadSessionMeta(path string) (codexSessionMeta, error) {
90		f, err := os.Open(path) //nolint:gosec // path discovered by walking the configured session dir
91		if err != nil {
92			return codexSessionMeta{}, fmt.Errorf("open rollout: %w", err)
93		}
94		defer func() { _ = f.Close() }()
95		r := bufio.NewReader(f)
96		first, err := r.ReadBytes('\n')
97		if len(first) == 0 && err != nil {
98			return codexSessionMeta{}, fmt.Errorf("read session_meta line: %w", err)
99		}
100		var line struct {
101			Type    string           `json:"type"`
102			Payload codexSessionMeta `json:"payload"`
103		}
104		if jsonErr := json.Unmarshal(first, &line); jsonErr != nil || line.Type != "session_meta" {
105			return codexSessionMeta{}, errors.New("first line is not session_meta")
106		}
107		return line.Payload, nil
108	}
109	
110	// SplitTurns produces one Turn per user response_item, bounded by the next.
111	// Codex response_items carry no per-message UUID, so the turn's stable key is
112	// its (append-only) start line index. Token usage is delegated to the Codex
113	// agent, which computes the cumulative-usage delta for the line range.
114	func (codexImporter) SplitTurns(_ SessionFile, full []byte) ([]Turn, error) {
115		rawLines := splitRawLines(full)
116		var starts []int
117		for i, raw := range rawLines {
118			if _, ok := codexPromptText(raw); ok {
119				starts = append(starts, i)
120			}
121		}
122	
123		ag := &codex.CodexAgent{}
124		turns := make([]Turn, 0, len(starts))
125		for k, start := range starts {
126			end := len(rawLines)
127			if k+1 < len(starts) {
128				end = starts[k+1]
129			}
130	
131			truncated := joinLines(rawLines[:end])
132			tokens, err := ag.CalculateTokenUsage(truncated, start)
133			if err != nil {
134				return nil, fmt.Errorf("token usage for turn %d: %w", k, err)
135			}
136	
137			prompt, _ := codexPromptText(rawLines[start])
138			ts := codexLineTime(rawLines[start])
139	
140			turns = append(turns, Turn{
141				LineStart: start,
142				LineEnd:   end,
143				UUID:      strconv.Itoa(start),
144				Prompt:    prompt,
145				CreatedAt: ts,
146				Tokens:    tokens,
147			})
148		}
149		return turns, nil
150	}
151	
152	// codexPromptText reports whether a raw rollout line is a user-prompt
153	// response_item and returns its concatenated input_text. Assistant messages,
154	// tool calls, and event_msg lines return false.
155	func codexPromptText(raw []byte) (string, bool) {
156		var line struct {
157			Type    string          `json:"type"`
158			Payload json.RawMessage `json:"payload"`
159		}
160		if err := json.Unmarshal(raw, &line); err != nil || line.Type != "response_item" {
161			return "", false
162		}
163		var payload struct {
164			Type    string `json:"type"`
165			Role    string `json:"role"`
166			Content []struct {
167				Type string `json:"type"`
168				Text string `json:"text"`
169			} `json:"content"`
170		}
171		if err := json.Unmarshal(line.Payload, &payload); err != nil {
172			return "", false
173		}
174		if payload.Type != "message" || payload.Role != "user" {
175			return "", false
176		}
177		var texts []string
178		for _, item := range payload.Content {
179			if item.Type == "input_text" {
180				if t := strings.TrimSpace(item.Text); t != "" {
181					texts = append(texts, t)
182				}
183			}
184		}
185		if len(texts) == 0 {
186			return "", false
187		}
188		return strings.Join(texts, "\n\n"), true
189	}
190	
191	// codexLineTime returns the RFC3339 timestamp on a rollout line, or the zero
192	// time when absent or unparseable.
193	func codexLineTime(raw []byte) time.Time {
194		var line struct {
195			Timestamp string `json:"timestamp"`
196		}
197		if err := json.Unmarshal(raw, &line); err != nil {
198			return time.Time{}
199		}
200		ts, err := time.Parse(time.RFC3339, line.Timestamp)
201		if err != nil {
202			return time.Time{}
203		}
204		return ts
205	}
206	
207	// repoMatches reports whether cwd is the repo root or a descendant of it. Both
208	// paths are normalized (cleaned, symlinks resolved best-effort) before
209	// comparison. Used by the global/flat-store importers (Codex, Copilot) to keep
210	// only sessions belonging to this repo.
211	func repoMatches(cwd, repoRoot string) bool {
212		if cwd == "" || repoRoot == "" {
213			return false
214		}
215		rel, err := filepath.Rel(normalizePath(repoRoot), normalizePath(cwd))
216		if err != nil {
217			return false
218		}
219		return !strings.HasPrefix(rel, "..")
220	}
221	
222	// normalizePath cleans a path and resolves symlinks when possible, so a cwd
223	// recorded through a symlinked path (e.g. macOS /var → /private/var) still
224	// matches the repo root. Falls back to the cleaned path when the target does
225	// not exist on this machine.
226	func normalizePath(p string) string {
227		cleaned := filepath.Clean(p)
228		if resolved, err := filepath.EvalSymlinks(cleaned); err == nil {
229			return resolved
230		}
231		return cleaned
232	}
